def merge_intervals(intervals):
    if not intervals:
        return []

    merged = [intervals[0]]
    for start, end in sorted(intervals[1:]):
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
